﻿const std = @import("std");
const parquet = @import("parquet");

const rows: usize = 1_000_000;
const repeats: usize = 5;

pub fn main(init: std.process.Init) !void {
    const allocator = init.gpa;
    const io = init.io;

    const values = try allocator.alloc(parquet.Optional(i64), rows);
    defer allocator.free(values);
    for (values, 0..) |*slot, i| slot.* = .{ .value = @intCast(i) };

    var stdout_buf: [512]u8 = undefined;
    var stdout_writer = std.Io.File.stdout().writerStreaming(io, &stdout_buf);
    const stdout = &stdout_writer.interface;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    if (args.len > 1) return readFile(allocator, io, stdout, args[1]);

    for (0..repeats) |n| {
        const write_start = std.Io.Timestamp.now(io, .awake);
        var writer = try parquet.writeToBuffer(allocator, &.{
            .{ .name = "id", .type_ = .int64, .optional = false },
        });
        defer writer.deinit();
        try writer.writeColumnOptional(i64, 0, values);
        try writer.close();
        const bytes = try writer.toOwnedSlice();
        defer allocator.free(bytes);
        const write_ns = write_start.durationTo(std.Io.Timestamp.now(io, .awake)).nanoseconds;

        const read_start = std.Io.Timestamp.now(io, .awake);
        var reader = try parquet.openBufferDynamic(allocator, bytes, .{});
        defer reader.deinit();
        var decoded = try parquet.readRowGroupAsArrow(allocator, reader.getSource(), reader.metadata, 0, null);
        defer decoded.deinit();
        const data: [*]const i64 = @ptrCast(@alignCast(decoded.arrays[0].buffers[1].?));
        const len: usize = @intCast(decoded.arrays[0].length);
        var sum: i64 = 0;
        for (data[0..len]) |value| sum += value;
        const read_ns = read_start.durationTo(std.Io.Timestamp.now(io, .awake)).nanoseconds;

        try stdout.print("{d} {d} {d} {d} {d}\n", .{ n, write_ns, read_ns, bytes.len, sum });
        try stdout.flush();
    }
}

/// Decode every row group of a real file into Arrow arrays, then re-encode those
/// arrays to an in-memory snappy Parquet file.
