const std = @import("std");
const builtin = @import("builtin");

/// Comptime string repetition; replaces `"s" ** n` (removed in Zig 0.17).
pub fn repeat(comptime s: []const u8, comptime n: usize) *const [s.len * n]u8 {
    comptime {
        @setEvalBranchQuota(10 * n + 1000);
        var buf: [s.len * n]u8 = undefined;
        for (0..n) |i| @memcpy(buf[i * s.len ..][0..s.len], s);
        const out = buf;
        return &out;
    }
}

const CData = extern struct { a: c_ulong, p: ?*anyopaque };
extern fn some_c_fn(x: c_int) c_int;

test "repeat" {
    const a = repeat("abcdefgh", 1000);
    try std.testing.expectEqual(@as(usize, 8000), a.len);
    try std.testing.expectEqualStrings("abcdefghabcd", a[0..12]);
    const big = repeat("ABCDEFGHIJKLMNOP", 256 * 1024 / 16);
    try std.testing.expectEqual(@as(usize, 256 * 1024), big.len);
    const z: [16]u8 = @splat(0);
    try std.testing.expectEqualSlices(u8, &@as([16]u8, @splat(0)), &z);
    const d = try std.testing.allocator.dupeSentinel(u8, "hi", 0);
    defer std.testing.allocator.free(d);
    try std.testing.expectEqual(@as(u32, 0x352441c2), std.hash.Crc32.hash("abc"));
    const ver = builtin.zig_version;
    try std.testing.expect(ver.major == 0 and (ver.minor == 16 or ver.minor == 17));
    if (false) _ = some_c_fn(1);
    _ = CData;
}

