fn assembleNestedRows(
    self: *Self,
    num_rows: usize,
    num_leaf_columns: usize,
    column_values: [][]Value,
    column_def_levels: []?[]u32,
    column_rep_levels: []?[]u32,
    top_infos: []const TopColInfo,
    projected_top_indices: ?[]const usize,
